gAQ(){return"\u0413\u043e\u0434\u0438\u043d\u043d\u0438\u043a \u0432\u0436\u0435 \u0441\u0438\u043d\u0445\u0440\u043e\u043d\u0456\u0437\u043e\u0432\u0430\u043d\u043e. \u042f\u043a\u0449\u043e \u0432\u0456\u043d \u0437\u0430\u0431\u0456\u0433 \u0437\u0430\u043d\u0430\u0434\u0442\u043e \u0434\u0430\u043b\u0435\u043a\u043e \u0432\u043f\u0435\u0440\u0435\u0434, \u043f\u0435\u0440\u0435\u0437\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0442\u0435 \u0441\u0435\u0440\u0432\u0435\u0440 \u043a\u0456\u043c\u043d\u0430\u0442\u0438 \u0442\u0430 \u0441\u0438\u043d\u0445\u0440\u043e\u043d\u0456\u0437\u0443\u0439\u0442\u0435 \u0439\u043e\u0433\u043e \u0437\u043d\u043e\u0432\u0443."},
gqm(){return"\u0413\u043e\u0434\u0438\u043d\u043d\u0438\u043a \u0432\u0436\u0435 \u0441\u0438\u043d\u0445\u0440\u043e\u043d\u0456\u0437\u043e\u0432\u0430\u043d\u043e. \u042f\u043a\u0449\u043e \u0432\u0456\u043d \u0437\u0430\u0431\u0456\u0433 \u0437\u0430\u043d\u0430\u0434\u0442\u043e \u0434\u0430\u043b\u0435\u043a\u043e \u0432\u043f\u0435\u0440\u0435\u0434, \u043f\u0435\u0440\u0435\u0437\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0442\u0435 \u0441\u0435\u043d\u0441\u043e\u0440 \u0456 \u0441\u0438\u043d\u0445\u0440\u043e\u043d\u0456\u0437\u0443\u0439\u0442\u0435 \u0439\u043e\u0433\u043e \u0437\u043d\u043e\u0432\u0443."},
