gDe(){return"\u0412\u0438 \u0432\u0438\u0439\u0448\u043b\u0438 \u0437 \u0446\u044c\u043e\u0433\u043e \u0440\u0435\u0442\u0440\u0430\u043d\u0441\u043b\u044f\u0442\u043e\u0440\u0430."},
glA(){return"\u041d\u0435\u043e\u0447\u0456\u043a\u0443\u0432\u0430\u043d\u0430 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u044c"},
gll(){return"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044c \u0440\u043e\u0437\u043f\u0456\u0437\u043d\u0430\u0442\u0438 \u043d\u0430\u043b\u0430\u0448\u0442\u0443\u0432\u0430\u043d\u043d\u044f \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0456\u0432 \u0440\u0430\u0434\u0456\u043e."},
goQ(){return"\u0424\u0443\u043d\u043a\u0446\u0456\u044f \u0441\u0443\u0441\u0456\u0434\u0456\u0432 \u043d\u0435 \u043f\u0456\u0434\u0442\u0440\u0438\u043c\u0443\u0454\u0442\u044c\u0441\u044f \u043f\u0440\u043e\u0448\u0438\u0432\u043a\u043e\u044e \u0446\u044c\u043e\u0433\u043e \u0440\u0435\u0442\u0440\u0430\u043d\u0441\u043b\u044f\u0442\u043e\u0440\u0430."},
gls(){return"\u0421\u043f\u0438\u0441\u043e\u043a \u0441\u0443\u0441\u0456\u0434\u0456\u0432 \u0446\u044c\u043e\u0433\u043e \u0440\u0435\u0442\u0440\u0430\u043d\u0441\u043b\u044f\u0442\u043e\u0440\u0430 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u0439."},
gij(){return"\u0429\u043e\u0431 \u043c\u0456\u043d\u0456\u043c\u0456\u0437\u0443\u0432\u0430\u0442\u0438 \u043c\u0435\u0440\u0435\u0436\u0435\u0432\u0438\u0439 \u0442\u0440\u0430\u0444\u0456\u043a, \u0432\u0438\u043a\u043e\u0440\u0438\u0441\u0442\u043e\u0432\u0443\u0439\u0442\u0435 \u0456\u043a\u043e\u043d\u043a\u0438 \u043e\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u0434\u043b\u044f \u0437\u0430\u043f\u0438\u0442\u0443 \u043f\u043e\u0442\u0440\u0456\u0431\u043d\u043e\u0457 \u0432\u0430\u043c \u0456\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u0457."},
giW(){return"\u0406\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u044f \u043f\u0440\u043e \u0432\u043b\u0430\u0441\u043d\u0438\u043a\u0430"},
gro(){return"\u0414\u043e\u0434\u0430\u0442\u0438 \u043f\u0443\u0431\u043b\u0456\u0447\u043d\u0456 \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u043d\u0456 \u0434\u0430\u043d\u0456."},
gBw(){return"\u0426\u0435\u0439 \u0440\u0435\u0442\u0440\u0430\u043d\u0441\u043b\u044f\u0442\u043e\u0440 \u043f\u043e\u0442\u0440\u0435\u0431\u0443\u0454 \u043e\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u043f\u0440\u043e\u0448\u0438\u0432\u043a\u0438, \u0449\u043e\u0431 \u0443\u0432\u0456\u043c\u043a\u043d\u0443\u0442\u0438 \u0456\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u044e \u043f\u0440\u043e \u0432\u043b\u0430\u0441\u043d\u0438\u043a\u0430."},
gkz(){return"\u041e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043d\u044f"},
gAC(){return"\u0420\u0435\u0442\u0440\u0430\u043d\u0441\u043b\u044f\u0442\u043e\u0440 \u043d\u0430\u0434\u0456\u0448\u043b\u0435 \u043e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043d\u044f \u0437 \u0440\u0435\u0442\u0440\u0430\u043d\u0441\u043b\u044f\u0446\u0456\u0454\u044e \u0447\u0435\u0440\u0435\u0437 \u0432\u0441\u044e \u043c\u0435\u0440\u0435\u0436\u0443."},
gji(){return"\u0406\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u0438 \u043e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u044c"},
gko(){return"\u0412\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0438 \u0456\u043d\u0442\u0435\u0440\u0432\u0430\u043b\u0438 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u0438\u0445 \u043e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u044c."},
gqt(){return"\u0412\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0438 \u0433\u0435\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u044e \u0440\u0435\u0442\u0440\u0430\u043d\u0441\u043b\u044f\u0442\u043e\u0440\u0430 \u043d\u0430 \u043a\u0430\u0440\u0442\u0456."},
glu(){return"\u0413\u0435\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u044f, \u044f\u043a\u0443 \u0432\u0438 \u0442\u0443\u0442 \u043d\u0430\u043b\u0430\u0448\u0442\u0443\u0454\u0442\u0435, \u0431\u0443\u0434\u0435 \u0442\u0440\u0430\u043d\u0441\u043b\u044e\u0432\u0430\u0442\u0438\u0441\u044f \u043f\u0443\u0431\u043b\u0456\u0447\u043d\u043e \u0447\u0435\u0440\u0435\u0437 \u0432\u0441\u044e \u043c\u0435\u0440\u0435\u0436\u0443, \u043a\u043e\u043b\u0438 \u0432\u0443\u0437\u043e\u043b \u043d\u0430\u0434\u0441\u0438\u043b\u0430\u0442\u0438\u043c\u0435 \u043e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043d\u044f. \u041a\u043e\u0436\u0435\u043d, \u0445\u0442\u043e \u043e\u0442\u0440\u0438\u043c\u0430\u0454 \u043e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043d\u044f, \u0437\u043c\u043e\u0436\u0435 \u043f\u043e\u0434\u0456\u043b\u0438\u0442\u0438\u0441\u044f \u0433\u0435\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u0454\u044e \u0437 \u0456\u043d\u0448\u0438\u043c\u0438, \u0437\u043e\u043a\u0440\u0435\u043c\u0430 \u0432 \u0406\u043d\u0442\u0435\u0440\u043d\u0435\u0442\u0456."},
